"C:\Users\o-neo\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe" -NoProfile -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$start = [datetime]'2026-09-14T00:15:00+03:00'
$end = Get-Date
'APPLICATION_RELEVANT_EVENTS'
try {
  Get-WinEvent -FilterHashtable @{LogName='Application'; StartTime=$start; EndTime=$end} -ErrorAction Stop |
    Where-Object { $_.Id -in 1000,1001,1002,1026,26 -or $_.ProviderName -match 'Application Error|Windows Error Reporting|Application Hang|\.NET Runtime' -or $_.Message -match '(?i)python\.exe|0xc0000|unknown software exception' } |
    Select-Object TimeCreated,Id,LevelDisplayName,ProviderName,RecordId,Message |
    Format-List
} catch {
  \"APPLICATION_LOG_INACCESSIBLE: $($_.Exception.Message)\"
}

'SYSTEM_RELEVANT_EVENTS'
try {
  Get-WinEvent -FilterHashtable @{LogName='System'; StartTime=$start; EndTime=$end} -ErrorAction Stop |
    Where-Object { $_.Message -match '(?i)python\.exe|0xc0000|unknown software exception' -or $_.ProviderName -eq 'Application Popup' } |
    Select-Object TimeCreated,Id,LevelDisplayName,ProviderName,RecordId,Message |
    Format-List
} catch {
  \"SYSTEM_LOG_INACCESSIBLE: $($_.Exception.Message)\"
}

'WER_LOGS_AVAILABILITY'
Get-WinEvent -ListLog '*WER*' -ErrorAction SilentlyContinue | Select-Object LogName,IsEnabled,RecordCount,LastWriteTime | Format-Table -AutoSize

'WER_OPERATIONAL_RELEVANT_EVENTS'
$werLogs = Get-WinEvent -ListLog '*WER*' -ErrorAction SilentlyContinue | Where-Object IsEnabled
foreach ($werLog in $werLogs) {
  try {
    Get-WinEvent -FilterHashtable @{LogName=$werLog.LogName; StartTime=$start; EndTime=$end} -ErrorAction Stop |
      Where-Object { $_.Message -match '(?i)python\.exe|0xc0000|unknown software exception' } |
      Select-Object @{n='LogName';e={$werLog.LogName}},TimeCreated,Id,ProviderName,RecordId,Message |
      Format-List
  } catch {
    \"WER_LOG_INACCESSIBLE $($werLog.LogName): $($_.Exception.Message)\"
  }
}"

